def policy(obs, P):
    x = obs[0]
    v = obs[1]
    if x <= P['x_left']:
        return 1
    if v >= P['v_high']:
        return 1
    if x >= P['x_right']:
        if v >= P['v_r_thr']:
            return 1
        return 2
    if x <= P['x_mid']:
        if v <= P['v_very_neg']:
            return 2
        if v <= P['v_thr'] and v >= P['v_low']:
            return 0
        if abs(v) < P['v_dead']:
            return 1
        return 2
    else:
        if v <= P['v_neg']:
            return 2
        if v >= P['v_mid_high'] and v < P['v_high']:
            return 1
        if abs(v) < P['v_dead']:
            return 1
        return 2
